using BULA;
using NUnit.Framework;
using Unity.Collections;
using Unity.Mathematics;
using UnityEngine;



// Smoke coverage for the Draw wireframe helpers. Debug.DrawLine is void and its output is not
// observable from a test, so these assert DoesNotThrow -- the same treatment Print.Spy and
// Print.Log(in floatBSR) get in DebugPrintTests, and for the same reason.
//
// What that still catches is worth having: every method builds an orthonormal frame from a
// caller-supplied direction and loops segment counts, so a bad basis, a divide by a zero-length axis
// or a non-positive segment count would throw or produce NaN here. The DEGENERATE cases below are the
// point of the file -- zero-length directions, a capsule whose endpoints coincide, and segment counts
// under the minimum are all reachable from a fit that did not converge, which is exactly when someone
// reaches for a debug draw.
//
// Managed thread only: Draw is not Burst-callable, like the rest of the Print/Export surface.
public class floatDrawTests
{
    static NativeArray<float3> Cloud(int n)
    {
        var pts = new NativeArray<float3>(n, Allocator.Temp);
        var rng = new Unity.Mathematics.Random(17u);
        for (int i = 0; i < n; i++)
            pts[i] = new float3((float)rng.NextDouble(-2.0, 2.0),
                                 (float)rng.NextDouble(-2.0, 2.0),
                                 (float)rng.NextDouble(-2.0, 2.0));
        return pts;
    }

    [Test]
    public void EveryShapeDraws()
    {
        var pts = Cloud(20);
        var axis = new float3((float)0.3, (float)1, (float)(-0.2));
        var origin = new float3((float)1, (float)2, (float)3);

        Assert.DoesNotThrow(() =>
        {
            Draw.points(pts, Color.grey);
            Draw.line(origin, axis, (float)4, Color.cyan);
            Draw.plane(origin, axis, (float)3, Color.blue);
            Draw.circle(origin, axis, (float)2, Color.white);
            Draw.sphere(origin, (float)1.5, Color.green);
            Draw.cylinder(origin, axis, (float)1, (float)3, Color.yellow);
            Draw.cone(origin, axis, (float)0.4, (float)3, Color.magenta);
            Draw.torus(origin, axis, (float)3, (float)0.8, Color.blue);
            Draw.capsule(origin, origin + (float)4 * axis, (float)1, Color.red);
            Draw.ellipse(new float2((float)1, (float)2), new float2((float)3, (float)1),
                         (float)0.5, Color.white);
        });

        pts.Dispose();
    }

    // An unset colour must become visible rather than silently transparent, and every shape must
    // accept `default` without special-casing at the call site.
    [Test]
    public void DefaultColourDraws()
    {
        var origin = new float3((float)0, (float)0, (float)0);
        var axis = new float3((float)0, (float)1, (float)0);

        Assert.DoesNotThrow(() =>
        {
            Draw.sphere(origin, (float)1);
            Draw.circle(origin, axis, (float)1);
            Draw.cylinder(origin, axis, (float)1, (float)2);
        });

        Assert.AreEqual(Color.white, Draw.Resolve(default), "an unset colour must resolve to white");
        Assert.AreEqual(Color.red, Draw.Resolve(Color.red), "an explicit colour must pass through");
    }

    // Degenerate inputs a non-converged fit can hand these: zero-length axes (the frame cannot be
    // built from them), a capsule collapsed to a point, and sub-minimum segment counts.
    [Test]
    public void DegenerateInputsDoNotThrow()
    {
        var zero = new float3((float)0, (float)0, (float)0);
        var p = new float3((float)1, (float)1, (float)1);

        Assert.DoesNotThrow(() =>
        {
            Draw.line(p, zero, (float)2);                       // no direction
            Draw.plane(p, zero, (float)2);
            Draw.circle(p, zero, (float)1);
            Draw.cylinder(p, zero, (float)1, (float)2);
            Draw.capsule(p, p, (float)1);                       // endpoints coincide -> sphere
            Draw.torus(p, zero, (float)2, (float)0.5);
            Draw.circle(p, new float3((float)0, (float)1, (float)0), (float)1, Color.white, 1);
            Draw.sphere(p, (float)1, Color.white, 0);           // segment count below the minimum
            Draw.ellipse(new float2((float)0, (float)0), new float2((float)1, (float)1),
                         (float)0, Color.white, 2);
        });
    }

    // The RANSAC companion: colours points by whether the model accepts them.
    [Test]
    public void ConsensusDrawsAgainstAModel()
    {
        var pts = Cloud(30);
        var model = new Fit.floatPlane
        {
            Point = new float3((float)0, (float)0, (float)0),
            Normal = new float3((float)0, (float)0, (float)1),
        };

        Assert.DoesNotThrow(() => Draw.consensus(pts, in model, (float)0.5));
        Assert.DoesNotThrow(() => Draw.consensus(pts, in model, (float)0.5, Color.cyan, Color.yellow));

        pts.Dispose();
    }
}
